{"command":"python3 <<'PY'
import subprocess, os, pty, select, time

def run_pty(exe, args, timeout=1.5):
    m,s=pty.openpty()
    env=os.environ.copy()
    env['TERM']='xterm-256color'
    proc=subprocess.Popen([exe]+args, stdin=s, stdout=s, stderr=s, env=env, close_fds=True)
    os.close(s)
    out=b""
    start=time.time()
    while time.time()-start<timeout:
        r,_,_=select.select([m],[],[],0.1)
        if r:
            try:
                out+=os.read(m,4096)
            except: break
        if proc.poll() is not None:
            break
    if proc.poll() is None:
        try:
            os.write(m,b'q')
        except: pass
        time.sleep(0.3)
        if proc.poll() is None:
            proc.kill()
    # drain
    for _ in range(5):
        r,_,_=select.select([m],[],[],0.05)
        if not r:
            break
        try:
            out+=os.read(m,4096)
        except: break
    os.close(m)
    proc.wait()
    return proc.returncode, out

